entries.dashboard=[entries.tasks[1],entries.tasks[2],entries.models[0],entries.orders[0]];
const names={dashboard:'驾驶舱',tasks:'任务',content:'内容灵感',models:'人偶模型',orders:'订单生产',audit:'数据审计'};
const intros={dashboard:'优先查看示例审批、风险与阻塞，再进入关联工作。',tasks:'从任务状态找到下一步动作，并查看关联业务对象。',content:'保留选题依据与关联关系，展示灵感到制作的推进方式。',models:'通过模型阶段和版本说明理解研发上下文。',orders:'以虚构订单展示生产交付状态，不展示个人或交易信息。',audit:'以虚构日志展示操作依据与状态变化。'};
let view='dashboard';const records=document.querySelector('#records'),detail=document.querySelector('#detail'),search=document.querySelector('#search');
function showDetail(r){document.querySelectorAll('.record').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===r[0])));detail.replaceChildren();const h=document.createElement('h2');h.textContent=r[1];detail.append(h);const status=document.createElement('span');status.className='badge';status.textContent=r[2];status.dataset.status=r[2];detail.append(status);const dl=document.createElement('dl');for(const [k,v] of [['演示编号',r[0]],['处理角色',r[4]],['摘要',r[3]],['关联对象',r[5]],['处理依据',r[6]]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;dl.append(dt,dd)}detail.append(dl)}
function resetDetail(){detail.innerHTML=`<div class="detail-intro-icon">${icon('models')}</div><h2>每一步，都有上下文。</h2><p>选择左侧记录，查看它的来源、关联与处理依据。</p><div class="context-steps"><div class="context-step"><i>01</i><div><b>定位当前状态</b><small>角色、阶段与下一步动作</small></div></div><div class="context-step"><i>02</i><div><b>追溯关联对象</b><small>串联选题、模型和订单</small></div></div><div class="context-step"><i>03</i><div><b>了解处理依据</b><small>关键决策保留人工确认</small></div></div></div>`;document.querySelectorAll('.record').forEach(b=>b.setAttribute('aria-pressed','false'))}
function render(){document.querySelector('#title').textContent=names[view];document.querySelector('#intro').textContent=intros[view];document.querySelector('#listTitle').textContent=view==='dashboard'?'优先处理':'示例记录';document.querySelector('#metrics').hidden=view!=='dashboard';document.querySelector('#metrics').innerHTML=[['待处理任务',entries.tasks.length,'tasks'],['内容选题',entries.content.length,'content'],['研发中模型',entries.models.length,'models'],['订单记录',entries.orders.length,'orders']].map(([k,v,i])=>`<div class="metric"><div class="metric-head"><span>${k}</span>${icon(i)}</div><b>${String(v).padStart(2,'0')}</b><span class="metric-foot">演示数据</span></div>`).join('');records.replaceChildren();const q=search.value.trim().toLowerCase();const list=entries[view].filter(r=>r.join(' ').toLowerCase().includes(q));for(const r of list){const b=document.createElement('button');b.className='record';b.dataset.id=r[0];b.setAttribute('aria-pressed','false');b.innerHTML=`<small>${r[0]}</small><h3>${r[1]}</h3><span class="badge" data-status="${r[2]}">${r[2]}</span><p>${r[3]}</p><div class="record-foot"><span>${r[4]}</span><span>查看详情 →</span></div>`;b.addEventListener('click',()=>showDetail(r));records.append(b)}if(!list.length){const p=document.createElement('p');p.className='empty';p.textContent='未找到匹配的示例记录';records.append(p)}}
document.querySelectorAll('[data-view]').forEach(b=>{b.innerHTML=icon(b.dataset.view)+`<span>${names[b.dataset.view]}</span><span class="nav-count">${String(entries[b.dataset.view].length).padStart(2,'0')}</span>`});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;search.value='';document.querySelectorAll('[data-view]').forEach(n=>{if(n===b)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});resetDetail();render()}));search.addEventListener('input',()=>{resetDetail();render()});document.querySelector('#clear').addEventListener('click',resetDetail);resetDetail();render();
